        h.palazzo.endCurrent();
        await settle();
        expect(h.palazzo.radioService.playInstant).toHaveBeenCalledTimes(1);
        expect(retriedCount(h)).toEqual([
          'alcantara_radio_bumpers_total{path="command",result="retried"} 0',
