      expect(urls(h.palazzo.commands)).toEqual([SONGS[0].url, SONGS[1].url]);
      expect(h.metrics.snapshot().handoffs).toEqual({ command: 1 });
    });

    it('not_ready withdrawal before the end: the next goes by command', async () => {
