      }
      return h.palazzo.radioService.playSong.mock.calls.map((call) => {
        const args = call as unknown[];
        return [
          args[0],
          args[1],
          args[2],
          args[3],
          typeof args[4],
          args[5],
          args[6],
        ];
      });
    }

    it('a session with no announcement accepted sends exactly the commands of today', async () => {
      const today = harness();
