  });

  describe('propose', () => {
    it('picks the best-matching sequence leaf', async () => {
      const { service } = await activeService();
      const proposal = service.propose('radio', {
        currentSongId: 1,
        currentArtist: 'A',
        leaves: [
          { leaf: leaf('i2', 2, 'B'), blocked: false },
